function finPlanoCalc(p){
  const atual=finLoad(FK.DESP);
  const byId=new Map(atual.map(x=>[String(x.id),x]));
  const chave=x=>[String(x.desc||'').toLowerCase().trim(),Number(x.valor).toFixed(2),x.data,x.parcelaAtual||1,x.totalParcelas||1].join('|');
  const chaves=new Set(atual.map(chave));
  const upd=(p.atualizar||[]).filter(u=>byId.has(String(u.id)));
  const semId=(p.atualizar||[]).length-upd.length;
  const cri=(p.criar||[]).filter(x=>x&&x.desc&&Number(x.valor)>0&&x.data&&!byId.has(String(x.id))&&!chaves.has(chave(x)));
  const exIds=new Set((p.excluirIds||[]).map(String));
  const regras=p.excluirDescContem||[];
  const exc=atual.filter(x=>exIds.has(String(x.id))||regras.some(r=>String(x.desc||'').toLowerCase().includes(r.texto)&&String(x.data)>=r.desde));
  return {atual,byId,upd,semId,cri,exc};
}
