function finPlanoAplicar(p){
  try{
    const c=finPlanoCalc(p);
    const bk=new Blob([JSON.stringify({tipo:'backup_despesas',em:new Date().toISOString(),despesas:c.atual})],{type:'application/json'});
    const a=document.createElement('a');a.href=URL.createObjectURL(bk);a.download='backup_despesas_antes_dos_ajustes_'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();
    const exIds=new Set(c.exc.map(x=>String(x.id)));
    const updMap=new Map(c.upd.map(u=>[String(u.id),u.set]));
    let lista=c.atual.filter(x=>!exIds.has(String(x.id))).map(x=>updMap.has(String(x.id))?Object.assign({},x,updMap.get(String(x.id))):x);
    c.cri.forEach(x=>{const o=Object.assign({},x);delete o._r;lista.push(o);});
    finSave(FK.DESP,lista);
    document.getElementById('modal-plano-desp')?.remove();
    fin_refresh();
    toast('✅ '+c.upd.length+' atualizados, '+c.cri.length+' criados, '+c.exc.length+' excluídos.');
  }catch(err){toast('❌ Erro ao aplicar: '+err.message);console.error(err);}
}
